/**
 * Base class for worker thread implementations. Handles communication with the main thread and provides RPC functionality.
 *
 * @remarks
 *
 * Extend this class when defining worker thread behavior. Uses `parentPort` for messaging with main thread. Constructor automatically signals readiness to main thread.
 *
 * @example
 * ```typescript
 * import { WorkerThreadInit, WorkerThreadExport, log } from "gramstax";
 *
 * class Worker extends WorkerThreadInit {
 *   constructor() {
 *     super(); // Required - signals ready to main thread
 *     log.info(`Worker ${this.id} started`);
 *   }
 *
 *   mtdProcess(data: any) {
 *     return { processed: data };
 *   }
 * }
 *
 * export const MyWorker = WorkerThreadExport.init({
 *   path: __filename,
 *   WTInit: Worker,
 * });
 * ```
 *
 * @public
 */

/**
 * Creates a new WorkerThreadInit instance. Sets up message handling and signals readiness to the main thread.
 */

/**
 * Manages worker thread lifecycle from the main thread. Handles spawning, communication, and termination of worker threads.
 *
 * @remarks
 *
 * Automatically registers SIGINT/SIGTERM handlers to terminate workers. Uses promise-based ready detection for synchronization.
 *
 * @example
 * ```typescript
 * import { WorkerThreadLaunch } from "gramstax";
 *
 * async function main() {
 *   const worker = new WorkerThreadLaunch("./jobs/processor.ts", ["config.json"]);
 *   await worker.ready();
 *   console.log(`Worker ${worker.threadId} is ready`);
 *
 *   const result = await worker.request("process", [{ data: "test" }]);
 *   console.log("Result:", result);
 *
 *   worker.kill();
 * }
 * ```
 *
 * @example
 *
 * Initialization method for handling requests from worker threads. Both can communicate with each other using an example like this, but this is very very rarely used.
 * ```typescript
 * import { WorkerThreadLaunch } from "gramstax";
 *
 * // main.ts
 * export class MainThread extends WorkerThreadLaunch {
 *   mtdHi() {
 *     // called from thread worker
 *     return `Hi, this is main thread`
 *   }
 * }
 *
 * async function main() {
 *   const worker = new MainThread("./jobs/processor.ts", ["config.json"]);
 *   await worker.ready();
 *   console.log(`Worker ${worker.threadId} is ready`);
 * }
 *
 * // jobs/processor.ts
 * import {MainThread} from "./main"
 * import {WorkerThreadInit} from "gramstax";
 *
 * class Worker extends WorkerThreadInit {
 *   constructor() {
 *     super();
 *     log.info(`Worker ${this.id} started`);
 *     this.request(`mtdHi`, []).then((res) => {
 *       res; // `Hi, this is main thread`
 *     })
 *   }
 * }
 * export const MyWorker = WorkerThreadExport.init({
 *   path: __filename,
 *   WTInit: MainThread,
 * });
 * ```
 *
 * @public
 */

/**
 * Manages multiple worker thread instances, providing pooled access and broadcast functionality.
 *
 * @remarks
 *
 * Uses `Map` with `threadId` as key for thread registry. Supports sending requests to all workers via broadcast.
 *
 * @example
 * ```typescript
 * import { WorkerThreadPool, WorkerThreadLaunch } from "gramstax";
 *
 * const workers = await Promise.all(
 *   [1, 2, 3, 4].map(async (i) => {
 *     const w = new WorkerThreadLaunch("./processor.ts", [String(i)]);
 *     await w.ready();
 *     return w;
 *   })
 * );
 *
 * const pool = new WorkerThreadPool(workers);
 * console.log(`Pool has ${pool.threadCount} workers`);
 *
 * // Broadcast to all workers
 * const statuses = await pool.broadcastRequest("getStatus", []);
 * ```
 *
 * @public
 */
